{
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Specific cues such as cold air, unexpected touch, and crowded places prompt her to keep her mind occupied, stay alert, avoid sleep, and seek out reminders in ways that manage the fear they evoke.",
      "quote": "“cold air, by being touched without warning, and by crowded places” ; “To manage this ongoing fear, she keeps her mind occupied almost all the time”"
    },
    "Triggers__Threat": {
      "weight": 8,
      "explanation": "The cues quickly make her feel as though she is back in danger, directly reactivating a current sense of threat.",
      "quote": "“can quickly make her feel as though she is back in danger”"
    },
    "Triggers__Memory": {
      "weight": 6,
      "explanation": "The vignette links the unsettling situations to her intrusive memory experiences, suggesting the cues reactivate the assault memory.",
      "quote": "“These memory experiences are tightly linked to the situations that unsettle her most”"
    },
    "Triggers__Negative_Appraisals": {
      "weight": 2,
      "explanation": "The triggers are described as making her feel unsafe, but the vignette does not clearly show them producing her beliefs about others or the assault.",
      "quote": "“make her feel as though she is back in danger”"
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "Her conviction that she cannot handle thinking about the event helps explain why she avoids settling into sleep and stays on alert.",
      "quote": "“if she thinks about the event, she will not be able to handle it”"
    },
    "Negative_Appraisals__Threat": {
      "weight": 8,
      "explanation": "Her belief that one can never know who will harm them sustains an ongoing sense of current danger and vigilance.",
      "quote": "“the conviction that one can never know who will harm them”"
    },
    "Negative_Appraisals__Memory": {
      "weight": 2,
      "explanation": "The vignette notes negative beliefs about the assault, but it does not directly state that these appraisals intensify the memory intrusions.",
      "quote": "“She also carries a painful belief”"
    },
    "Negative_Appraisals__Triggers": {
      "weight": 2,
      "explanation": "Her beliefs about danger are mentioned alongside the cues, but no direct causal link from appraisals to specific triggers is stated.",
      "quote": "“The memory experiences are tightly linked to the situations that unsettle her most”"
    },
    "Memory__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Her intrusive, recurring memory experiences are described as accompanying the fear she manages by staying occupied, alert, and avoiding sleep.",
      "quote": "“the intrusions that accompany it”"
    },
    "Memory__Threat": {
      "weight": 8,
      "explanation": "When she remembers the assault, it feels as if it is happening right now, which directly feeds immediate threat.",
      "quote": "“it feels as if it is happening right now”"
    },
    "Memory__Negative_Appraisals": {
      "weight": 6,
      "explanation": "The intrusive memory and lack of coherent narrative are part of a picture that leads her to believe danger is ever-present and that someone else should have stopped it.",
      "quote": "“Her memory of the assault is not organized into a coherent story”"
    },
    "Memory__Triggers": {
      "weight": 8,
      "explanation": "The vignette says the memory experiences are tightly linked to the situations that unsettle her most, indicating those cues reactivate the memory.",
      "quote": "“tightly linked to the situations that unsettle her most”"
    },
    "Threat__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Because she feels constant danger, she keeps her mind occupied, stays alert, avoids sleep, and watches for dangerous people.",
      "quote": "“living with the constant sense of danger” ; “she keeps her mind occupied almost all the time and stays alert for dangerous people”"
    },
    "Threat__Memory": {
      "weight": 6,
      "explanation": "Her current sense of danger co-occurs with and is reinforced by the intrusive memory states, though the vignette does not state a direct causal pathway from threat to memory.",
      "quote": "“feed her sense of immediate threat”"
    },
    "Threat__Negative_Appraisals": {
      "weight": 6,
      "explanation": "Persistent threat is paired with her belief that one can never know who will harm them, suggesting the threat state supports that appraisal.",
      "quote": "“feed her sense of immediate threat, deepening her hypervigilance” ; “the conviction that one can never know who will harm them”"
    },
    "Threat__Triggers": {
      "weight": 2,
      "explanation": "The vignette describes cues evoking threat, but not threat generating new triggers.",
      "quote": "“make her feel as though she is back in danger”"
    },
    "Maladaptive_Strategies__Memory": {
      "weight": 2,
      "explanation": "She seeks conversation, stays up late, and puts her body under stress, but the vignette does not clearly show these strategies causing more memory intrusions.",
      "quote": "“seeks out conversation with others about what happened”"
    },
    "Maladaptive_Strategies__Negative_Appraisals": {
      "weight": 0,
      "explanation": "No clear evidence shows her coping behaviors directly producing her negative beliefs.",
      "quote": ""
    }
  }
}
